public class Logs {
  public static void main(String[] args) {
      double[] arr = {1, 2, 3, 4, 5, 6, 7, 8, 9};
      double[] logs = new double[arr.length];

      for (int i = 0; i < arr.length; i++) {
          // En Java solo existe Log10 y Log natural (Math.log).
          // Para base 2, se requiere la fórmula de cambio de base (log(x) / log(2))
          logs[i] = Math.log(arr[i]) / Math.log(2);
      }
      System.out.println(java.util.Arrays.toString(logs));
  }
}
